--初始化伤害奖励
function UIWorldBossRankRewardDialog:InitHurtReward()
    if self._hurtRewards then
        return 
    end
    self._hurtRewards = worldBossComponent:GetAllReward()
    if not self._hurtRewards then
        self._hurtRewards = {}
    end

    local info = worldBossComponent:GetCurRankInfo()
    table.sort(self._hurtRewards, function(a, b)
        local isDrawA = worldBossComponent:IsDrawReward(a.id)
        local isDrawB = worldBossComponent:IsDrawReward(b.id)
        
        if isDrawA ~= isDrawB then
            if isDrawB then
                return true
            end
        elseif isDrawA and isDrawB then
            return checkNumber(a.upperLimit) < checkNumber(b.upperLimit)
        else
            local isCanDrawA = checkNumber(info.hurt) >= checkNumber(a.upperLimit)
            local isCanDrawB = checkNumber(info.hurt) >= checkNumber(b.upperLimit) 

            if isCanDrawA ~= isCanDrawB then
                if isCanDrawA then
                    return true
                end
            else
                return checkNumber(a.upperLimit) < checkNumber(b.upperLimit)
            end
        end

        return false
    end)
    
    --[[
    local t = CfUtils.GetCfTable(AutoIds.IdSetting976)
    if not t then
        return
    end
    for k, v in pairs(t) do
        local vo = WorldBossHurtRewardVo.New()
        vo:FillVo(v)
        table.insert(self._hurtRewards, vo)
    end 
    ]]
end

--初始化排名奖励
function UIWorldBossRankRewardDialog:InitRankReward()
    if self._rankRewards then
        return
    end

    self._rankRewards = {}
    local t = CfUtils.GetCfTable(AutoIds.IdSetting978)
    if not t then
        return
    end
    for k, v in pairs(t) do
        local vo = WorldBossRankRewardVo.New()
        vo:FillVo(v)
        table.insert(self._rankRewards, vo)
    end 
end

function UIWorldBossRankRewardDialog:FillHurt()
    KTool.SetActive(self.FontStyleButton, self:IsCanOnkeyDraw())

    if not self._isInitHurtView then
        self.RankingLoopView:InitListView(#self._hurtRewards, Bind(self, self.OnGetHurtCellByIndex))
        self._isInitHurtView = true
    else
        --GameUtils.ReloadData(self.RankingLoopView, #self._hurtRewards)
    end
end

function UIWorldBossRankRewardDialog:OnGetHurtCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._hurtRewards[index + 1]
    local cell = listView:NewListViewItem("Cell") 
    local scr = CfUtils.GetLuaScr(cell.gameObject, UIWorldBossRankRewardCellNode)
    if scr then
        scr:RefreshHurtReward(data, function()
            KTool.SetActive(self.FontStyleButton, self:IsCanOnkeyDraw())
        end)
        scr:PlayAni("Go")
    end

    return cell
end

function UIWorldBossRankRewardDialog:FillRank()
    if not self._isInitRankView then
        self.RankingLoopView:InitListView(#self._rankRewards, Bind(self, self.OnGetRankCellByIndex))
        self._isInitRankView = true
    else
        --GameUtils.ReloadData(self.RankingLoopView, #self._rankRewards)
    end
end

function UIWorldBossRankRewardDialog:OnGetRankCellByIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._rankRewards[index + 1]
    local cell = listView:NewListViewItem("Cell") 
    local scr = CfUtils.GetLuaScr(cell.gameObject, UIWorldBossRankRewardCellNode)
    if scr then
        scr:RefreshRankReward(data, index)
        scr:PlayAni("Go")
    end

    return cell
end

--伤害
function UIWorldBossRankRewardDialog:OnBtnHurt()
    self._type = TYPE.HURT
    self:InitHurtReward()
    self:FillHurt()
end

--排名
function UIWorldBossRankRewardDialog:OnBtnRank()
    self._type = TYPE.RANK
    self:InitRankReward()
    self:FillRank()
end

--一键领取
function UIWorldBossRankRewardDialog:OnBtnDrawAllReward()
    local info = worldBossComponent:GetCurRankInfo()
    local meHurt = checkNumber(info.hurt)

    worldBossComponent:WorldBossdrawHurtRewardReq(nil, function(rewardData)
        for k, v in pairs(self._hurtRewards) do
            if meHurt >= checkNumber(v.upperLimit) then
                worldBossComponent:SetRewardDraw(v.id)
            end
        end
        GameUtils.ReloadData(self.RankingLoopView, #self._hurtRewards)
        KTool.SetActive(self.FontStyleButton, self:IsCanOnkeyDraw())
        GameUtils.SetRedPointNum(Constants.RedPointConst.WorldBossReward, worldBossComponent:IsCanDrawReward())
    end)
end

